using AfriWallet.Fraud.Signals.Application.Abstractions;using AfriWallet.Fraud.Signals.Application.Commands;using AfriWallet.Fraud.Signals.Application.Results;using AfriWallet.Fraud.Signals.Domain.Aggregates;using AfriWallet.Fraud.Signals.Domain.ValueObjects;
namespace AfriWallet.Fraud.Signals.Application.Services;
public sealed class FraudSignalService(IFraudSignalRepository repository,IFraudSignalAuditStore audit,ISystemClock clock){public async Task<RecordFraudSignalResult> RecordAsync(RecordFraudSignalCommand command,CancellationToken ct=default){if(await repository.ExistsByEventIdAsync(command.EventId,ct))return new RecordFraudSignalResult(Guid.Empty,command.EventId,true);var signal=FraudSignal.Create(command.EventId,command.Source,command.Type,command.Severity,FraudSubject.Create(command.SubjectType,command.SubjectId),command.OccurredAt,clock.UtcNow,command.Attributes);await repository.AddAsync(signal,ct);await audit.AppendAsync(signal.Id,"FRAUD_SIGNAL_RECORDED",clock.UtcNow,ct);return new RecordFraudSignalResult(signal.Id,signal.EventId,false);} }